-- 0263 · Las FICHAS TÉCNICAS de las telas, adentro de Programa Core (13/10/2026)
--
-- Tamara: los vendedores entraban a F. técnica (un programa aparte, en Render,
-- con clave propia) y "se van y es difícil volver". Decisión: copiarlas acá
-- (caso B) y que se editen desde /admin/fichas-tecnicas (opción "a": copia
-- única; el programa de afuera no se vuelve a leer).
--
-- Copia de las 90 fichas tal como estaban el 13/10/2026 (REV. 01, Julio 2026),
-- leídas de los .docx del sitio. Lo que es IGUAL en las 90 (observaciones
-- técnicas, compromiso ambiental, firmas) no va por fila: vive en
-- modules/mi_cartera/fichas.py.
--
--   spec    — [[descripción, parámetro, unidad, especificación], …] en el orden
--             de la hoja (COMPOSICIÓN, CARACTERÍSTICAS, ENCOGIMIENTO, ELONGACIÓN).
--   lavado  — las instrucciones de cuidado, en orden. El símbolo sale del texto.
--
-- Permiso `fichas.editar` SIN ningún rol: edita sólo quien tiene `*`.

CREATE TABLE IF NOT EXISTS scintela.ficha_tecnica (
    codigo          VARCHAR(40)   PRIMARY KEY,
    nombre          VARCHAR(80)   NOT NULL,
    seccion         VARCHAR(10)   NOT NULL CHECK (seccion IN ('tubular', 'abierto')),
    grupo           VARCHAR(30)   NOT NULL,
    revision        VARCHAR(10)   NOT NULL DEFAULT '01',
    emision         VARCHAR(30)   NOT NULL,
    spec            JSONB         NOT NULL,
    lavado          JSONB         NOT NULL,
    orden           INTEGER       NOT NULL DEFAULT 0,
    activa          BOOLEAN       NOT NULL DEFAULT TRUE,
    actualizado_en  TIMESTAMPTZ   NOT NULL DEFAULT now(),
    actualizado_por VARCHAR(60)
);

